// Academic stage selector appears inside every subject-focused game.
function addAcademicStageSelector(game){
 const intro=$('#gameIntro');if(!intro)return;
 const wrap=document.createElement('div');wrap.className='mode-row academic-stage-row';wrap.style.marginTop='10px';
 wrap.innerHTML=`<label style="align-self:center;color:#aebce0;font-weight:700">STUDY STAGE</label><select id="academicStageSelect" class="game-btn" style="min-width:220px">${academicStages.map((name,i)=>`<option value="${i}" ${academicStage===i?'selected':''}>${name}</option>`).join('')}</select><label style="align-self:center;color:#aebce0;font-weight:700">LANGUAGE</label><select id="academicLanguageSelect" class="game-btn" style="min-width:160px"><option value="en" ${academicLanguage==='en'?'selected':''}>English</option><option value="zh" ${academicLanguage==='zh'?'selected':''}>中文</option><option value="ms" ${academicLanguage==='ms'?'selected':''}>Bahasa Melayu</option></select><span style="color:#9eb0d8;align-self:center">Choose stage and language</span>`;
 intro.appendChild(wrap);$('#academicStageSelect').onchange=e=>{academicStage=Number(e.target.value);launch(game);};$('#academicLanguageSelect').onchange=e=>{academicLanguage=e.target.value;launch(game);};
}

// Shared level selector: all games expose 10 increasingly challenging levels.
function addLevelSelector(game){
 const intro=$('#gameIntro');if(!intro)return;
 const wrap=document.createElement('div');wrap.className='mode-row';wrap.style.marginTop='12px';wrap.innerHTML=`<label style="align-self:center;color:#aebce0;font-weight:700">LEVEL</label><select id="gameLevelSelect" class="game-btn" style="min-width:150px">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${gameLevel===i+1?'selected':''}>Level ${i+1}${i===9?' · MASTER':''}</option>`).join('')}</select><span style="color:#9eb0d8;align-self:center">${gameLevel<=3?'Warm-up':gameLevel<=6?'Advanced':'Expert mode'}</span>`;
 intro.appendChild(wrap);$('#gameLevelSelect').onchange=e=>{gameLevel=Number(e.target.value);launch(game);};
}
