function renderSubjectGame(game){const names={science:'Science Showdown',history:'History Quest',geography:'Geo Genius',coding:'Code Breaker',vocabulary:'Word Wizard'};const bank=(academicLanguage!=='en'&&localizedSubjectBanks[academicLanguage]?.[game])?localizedSubjectBanks[academicLanguage][game]:(subjectBanks[game]||subjectBanks.science);
 $('#gameIntro').innerHTML=`<h2>${names[game]} <span style="color:#55e6e9">/ Expert Challenge</span></h2><p>Ten questions per round. Choose a study stage and English, 中文, or Bahasa Melayu where translations are available. English grammar and coding terminology may remain in English for subject accuracy. Works offline.</p>`;
 $('#gameArea').innerHTML='<div class="quiz-box" id="subjectQuiz"></div>';let order=[],idx=0,score=0,answered=false;
 function begin(){const stageRanges=[[0,.35],[0,.5],[.15,.7],[.3,.9],[.45,1],[.6,1]];const [startFrac,endFrac]=stageRanges[academicStage];let pool=Array.from({length:bank.length},(_,i)=>i).filter(i=>i>=Math.floor(bank.length*startFrac)&&i<Math.max(1,Math.ceil(bank.length*endFrac)));if(!pool.length)pool=bank.map((_,i)=>i);if(pool.length<Math.min(10,bank.length))pool=bank.map((_,i)=>i);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}order=pool.slice(0,Math.min(10,pool.length));idx=0;score=0;show();}
 function show(){answered=false;const q=bank[order[idx]%bank.length];const correctText=q[1][q[2]];const choices=q[1].map((v,i)=>({v,i}));for(let k=choices.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[choices[k],choices[j]]=[choices[j],choices[k]];}const shown=choices.map(c=>c.v);const correct=shown.indexOf(correctText);$('#subjectQuiz').innerHTML=`<div class="quiz-progress"><i style="width:${idx*10}%"></i></div><div class="quiz-meta"><span>${academicStages[academicStage]} · QUESTION ${idx+1}/${order.length}</span><span>SCORE ${score}</span></div><h3 class="quiz-question">${q[0]}</h3><div class="quiz-options">${shown.map((a,i)=>`<button class="quiz-option" data-sub-answer="${i}">${String.fromCharCode(65+i)}. ${a}</button>`).join('')}</div><div id="subjectFeedback" class="quiz-feedback"></div><div class="game-actions"><button class="game-btn hidden" id="subjectNext">${idx===order.length-1?'View results':'Next question →'}</button></div>`;$$('[data-sub-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.subAnswer),correct,q[3]));}
 function answer(n,c,explain){if(answered)return;answered=true;$$('[data-sub-answer]').forEach((b,i)=>{b.disabled=true;if(i===c)b.classList.add('correct');if(i===n&&n!==c)b.classList.add('wrong');});if(n===c){score++;addRewards(10+gameLevel*2,2+Math.floor(gameLevel/3));$('#subjectFeedback').textContent='Correct! '+explain;}else $('#subjectFeedback').textContent='Not quite. '+explain;$('#subjectNext').classList.remove('hidden');}
 $('#subjectQuiz').onclick=e=>{if(e.target.id!=='subjectNext')return;idx++;if(idx>=order.length){$('#subjectQuiz').innerHTML=`<div class="end-card"><div class="big-emoji">${score>=8?'🏆':'🧠'}</div><h2>${score>=8?'Expert round cleared!':'Challenge complete!'}</h2><p>Level ${gameLevel}: <b>${score}/10</b>. ${score>=8?'Brilliant work!':'Raise your level and try again.'}</p><button class="game-btn" id="subjectAgain">▶ Another round</button></div>`;$('#subjectAgain').onclick=begin;}else show();};begin();cleanupGame=()=>{};
}
function renderTypingBlitz(){const words=['conscientious','photosynthesis','metamorphosis','unprecedented','characteristic','infrastructure','misinterpretation','electromagnetic','juxtaposition','extraordinary','synchronisation','intercontinental'];$('#gameIntro').innerHTML='<h2>Typing Blitz <span style="color:#55e6e9">/ Accuracy Run</span></h2><p>Type the displayed word exactly. Higher levels use longer words.</p>';$('#gameArea').innerHTML='<div class="quiz-box"><div class="quiz-meta"><span>WORDS CLEARED</span><b id="typeScore">0</b><span>LEVEL '+gameLevel+'</span></div><h3 class="quiz-question" id="typeWord"></h3><form id="typeForm" class="math-form"><input id="typeInput" autocomplete="off" placeholder="Type the word exactly"><button class="game-btn">Submit</button></form><div id="typeFeedback" class="quiz-feedback"></div></div>';let score=0,idx=0;function next(){let pool=words.filter(w=>w.length>=Math.min(7+gameLevel,15));$('#typeWord').textContent=pool[Math.floor(Math.random()*pool.length)]||words[0];$('#typeInput').value='';$('#typeInput').focus();}$('#typeForm').onsubmit=e=>{e.preventDefault();if($('#typeInput').value===$('#typeWord').textContent){score++;idx++;$('#typeScore').textContent=score;$('#typeFeedback').textContent='Perfect typing!';addRewards(5+gameLevel,1);next();}else $('#typeFeedback').textContent='Not exact — check every letter and try again.';};next();cleanupGame=()=>{};}
function renderMemoryMatrix(){ $('#gameIntro').innerHTML='<h2>Memory Matrix <span style="color:#55e6e9">/ Sequence Test</span></h2><p>Memorize the sequence and enter it in order. Every level starts with a longer sequence.</p>';$('#gameArea').innerHTML='<div class="quiz-box"><div class="quiz-meta"><span>ROUND</span><b id="memoryRound">1</b><span>LEVEL '+gameLevel+'</span></div><h3 class="quiz-question" id="memorySequence">Ready?</h3><form id="memoryForm" class="math-form"><input id="memoryAnswer" autocomplete="off" placeholder="Enter digits in order"><button class="game-btn">Check</button></form><div id="memoryFeedback" class="quiz-feedback"></div><button id="memoryStart" class="game-btn alt">Show next sequence</button></div>';let round=1,seq='';function show(){seq=Array.from({length:Math.min(3+gameLevel+round-1,14)},()=>Math.floor(Math.random()*10)).join('');$('#memorySequence').textContent=seq;$('#memoryAnswer').value='';$('#memoryAnswer').disabled=true;setTimeout(()=>{if(currentGame==='memory'){$('#memorySequence').textContent='Now recall it!';$('#memoryAnswer').disabled=false;$('#memoryAnswer').focus();}},Math.max(700,2400-gameLevel*130));}$('#memoryStart').onclick=show;$('#memoryForm').onsubmit=e=>{e.preventDefault();if($('#memoryAnswer').value===seq){round++;$('#memoryRound').textContent=round;$('#memoryFeedback').textContent='Correct — sequence gets longer!';addRewards(8+gameLevel,2);show();}else $('#memoryFeedback').textContent='Not quite. Press “Show next sequence” to try a new one.';};show();cleanupGame=()=>{};}
function renderReactionRush(){ $('#gameIntro').innerHTML='<h2>Reaction Rush <span style="color:#55e6e9">/ Reflex Lab</span></h2><p>Press the button only when it turns green. False starts count as a miss.</p>';$('#gameArea').innerHTML='<div class="quiz-box"><div class="quiz-meta"><span>BEST REACTION</span><b id="reactionBest">—</b><span>LEVEL '+gameLevel+'</span></div><button id="reactionTarget" class="game-btn" style="width:100%;min-height:170px;font-size:1.5rem">Click to begin</button><div id="reactionFeedback" class="quiz-feedback"></div></div>';let phase='idle',start=0,timeout=null,best=Infinity;const target=$('#reactionTarget');target.onclick=()=>{if(phase==='idle'||phase==='done'){phase='wait';target.textContent='Wait for GREEN…';target.style.background='#a34a66';$('#reactionFeedback').textContent='Stay ready…';timeout=setTimeout(()=>{phase='go';start=performance.now();target.textContent='CLICK NOW!';target.style.background='#15976e';},800+Math.random()*Math.max(500,2600-gameLevel*180));}else if(phase==='wait'){clearTimeout(timeout);phase='done';target.textContent='False start! Click to retry';target.style.background='#a34a66';$('#reactionFeedback').textContent='Too early! Wait for green.';}else if(phase==='go'){let ms=Math.round(performance.now()-start);phase='done';target.textContent='Your time: '+ms+' ms — click to retry';target.style.background='#263657';$('#reactionFeedback').textContent=ms<250?'Lightning fast!':ms<350?'Nice reaction!':'Keep practising!';if(ms<best){best=ms;$('#reactionBest').textContent=ms+' ms';}addRewards(Math.max(1,Math.round((500-ms)/50)),1);}};cleanupGame=()=>clearTimeout(timeout);}

// Settings: local preferences, synthetic background music, sound feedback, FPS and network estimate.
const settingsDefaults={music:true,sfx:true,musicVolume:100,sfxVolume:100,overlay:true,reduceMotion:false,tips:true};
let settings={...settingsDefaults};
try{settings={...settingsDefaults,...JSON.parse(localStorage.getItem('aplusSettings')||'{}')}}catch(e){}
let audioCtx=null,musicTimer=null,musicStep=0,musicGain=null,lastFpsStamp=performance.now(),fpsFrames=0,fps=0,networkInterval=null;
function saveSettings(){try{localStorage.setItem('aplusSettings',JSON.stringify(settings))}catch(e){}}
function syncSettingsUI(){
 const pairs=[['musicToggle','music'],['sfxToggle','sfx'],['overlayToggle','overlay'],['reduceMotionToggle','reduceMotion'],['tipsToggle','tips']];
 pairs.forEach(([id,key])=>{const el=document.getElementById(id);if(el)el.checked=!!settings[key]});
 [['musicVolume','musicVolume','musicVolumeLabel'],['sfxVolume','sfxVolume','sfxVolumeLabel']].forEach(([id,key,label])=>{const el=document.getElementById(id),out=document.getElementById(label);if(el)el.value=settings[key];if(out)out.textContent=settings[key]+'%'});
 document.body.classList.toggle('reduce-motion',!!settings.reduceMotion);
}
function ensureAudio(){if(!audioCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;audioCtx=new AC();musicGain=audioCtx.createGain();musicGain.gain.value=(settings.musicVolume/100)*0.42;musicGain.connect(audioCtx.destination);}if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});return audioCtx;}
function tone(freq,duration=0.12,type='sine',volume=.08){const ac=ensureAudio();if(!ac||!settings.sfx)return;const osc=ac.createOscillator(),gain=ac.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.value=(settings.sfxVolume/100)*Math.min(.35,volume*2.5);osc.connect(gain);gain.connect(ac.destination);osc.start();gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);osc.stop(ac.currentTime+duration);}
function stopMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null;}}
function startMusic(){
 stopMusic();const ac=ensureAudio();if(!ac||!settings.music)return;if(ac.state==='suspended')ac.resume().catch(()=>{});musicStep=0;
 // Original, procedurally generated arcade loop: no audio downloads or internet required.
 const melody=[523.25,659.25,783.99,659.25,587.33,698.46,880,698.46,523.25,659.25,987.77,880,783.99,698.46,659.25,587.33];
 const bass=[130.81,130.81,164.81,164.81,174.61,174.61,146.83,146.83];
 const play=(freq,dur,when,vol,wave='triangle')=>{const o=ac.createOscillator(),g=ac.createGain();o.type=wave;o.frequency.setValueAtTime(freq,when);g.gain.setValueAtTime(0.0001,when);g.gain.linearRampToValueAtTime((settings.musicVolume/100)*Math.min(.48,vol*2.4),when+.025);g.gain.exponentialRampToValueAtTime(.0001,when+dur);o.connect(g);g.connect(musicGain);o.start(when);o.stop(when+dur+.02);};
 musicTimer=setInterval(()=>{if(!settings.music||!musicGain||ac.state!=='running')return;const step=musicStep++%melody.length,now=ac.currentTime;play(melody[step],.22,now,.16,'triangle');if(step%2===0)play(bass[(step/2)%bass.length],.36,now,.13,'sine');if(step%4===0){play(melody[step]/2,.42,now,.035,'sine');}},230);
}
// Start audio after the first real user gesture (desktop browser autoplay policy).
const unlockArcadeAudio=()=>{if(settings.music){ensureAudio();if(!musicTimer)startMusic();}window.removeEventListener('pointerdown',unlockArcadeAudio);window.removeEventListener('keydown',unlockArcadeAudio);};
window.addEventListener('pointerdown',unlockArcadeAudio);window.addEventListener('keydown',unlockArcadeAudio);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&settings.sfx&&!b.disabled&&!b.matches('[data-sub-answer]'))tone(520,.045,'triangle',.035);});
function applyAudio(){if(settings.music)startMusic();else stopMusic();if(musicGain)musicGain.gain.value=(settings.musicVolume/100)*.42;}
function tickFps(now){fpsFrames++;if(now-lastFpsStamp>=1000){fps=Math.round(fpsFrames*1000/(now-lastFpsStamp));fpsFrames=0;lastFpsStamp=now;const el=document.getElementById('fpsValue');if(el)el.textContent=fps;const top=document.getElementById('fpsTopValue');if(top)top.textContent=fps;}requestAnimationFrame(tickFps);}
requestAnimationFrame(tickFps);
async function refreshNetwork(){
 const pingEl=document.getElementById('pingValue'),pingLabel=document.getElementById('pingLabel'),scoreEl=document.getElementById('internetScore'),scoreBar=document.getElementById('internetScoreBar'),scoreLabel=document.getElementById('internetLabel'),stateEl=document.getElementById('connectionState'),timeEl=document.getElementById('networkCheckedAt');
 if(!pingEl)return;
 pingEl.textContent='…';pingLabel.textContent='testing connection';scoreEl.textContent='…';scoreLabel.textContent='testing connection';
 const start=performance.now();
 try{
   const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),4500);
   await fetch('https://www.gstatic.com/generate_204?cacheBust='+Date.now(),{mode:'no-cors',cache:'no-store',signal:controller.signal});
   clearTimeout(timeout);
   const ms=Math.max(1,Math.round(performance.now()-start));
   pingEl.textContent=ms+' ms';pingLabel.textContent=ms<60?'Very responsive':ms<150?'Good response':'Slow response';
   // A simple, clearly-labelled 0–10 responsiveness estimate, not a bandwidth test.
   const rating=Math.max(0,Math.min(10,Math.round(10-ms/45)));
   scoreEl.textContent=rating;scoreBar.style.width=(rating*10)+'%';scoreLabel.textContent=rating>=8?'Excellent response':rating>=5?'Fair response':'Slow response';
   stateEl.textContent='Online (check succeeded)';stateEl.style.color='#80f4d2';
 }catch(e){
   pingEl.textContent='N/A';pingLabel.textContent='unavailable / blocked';scoreEl.textContent='—';scoreBar.style.width='0%';scoreLabel.textContent='no reliable connection result';stateEl.textContent=navigator.onLine?'Check blocked or timed out':'Offline';stateEl.style.color='#ffad9e';
 }
 timeEl.textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});
}
function bindSetting(id,key,transform=v=>v){const el=document.getElementById(id);if(!el)return;el.addEventListener('change',()=>{settings[key]=transform(el.type==='checkbox'?el.checked:Number(el.value));saveSettings();syncSettingsUI();if(key==='music'||key==='musicVolume')applyAudio();if(key==='sfx')tone(660,.08);});}
bindSetting('musicToggle','music');bindSetting('sfxToggle','sfx');bindSetting('overlayToggle','overlay');bindSetting('reduceMotionToggle','reduceMotion');bindSetting('tipsToggle','tips');bindSetting('musicVolume','musicVolume',v=>Math.max(0,Math.min(100,v)));bindSetting('sfxVolume','sfxVolume',v=>Math.max(0,Math.min(100,v)));
$('#refreshNetwork')?.addEventListener('click',refreshNetwork);
$('#settingsShortcut')?.addEventListener('click',()=>showPage('settings'));
$('#resetSettings')?.addEventListener('click',()=>{settings={...settingsDefaults};saveSettings();syncSettingsUI();applyAudio();tone(520,.08);});
syncSettingsUI();
window.addEventListener('online',()=>{if(currentGame==='settings')refreshNetwork()});
window.addEventListener('offline',()=>{if(currentGame==='settings')refreshNetwork()});
